B.aQQ=new A.eD("Ek kredi uygulama i\xe7i sat\u0131n alma ile edinilebilir",null)
B.aQP=new A.eD("Sat\u0131n al\u0131nan krediler iade edilemez",null)
B.aUI=new A.j6("Kabul Edilebilir Kullan\u0131m",null)
B.aTb=new A.iJ("Uygulamay\u0131 yaln\u0131zca ki\u015fisel mekan analizi ama\xe7l\u0131 kullanabilirsiniz. A\u015fa\u011f\u0131daki davran\u0131\u015flar yasakt\u0131r:",null)
